// Toy byte-pair encoding: learn merges from a corpus, then encode new words.
type Pair = `${string}\u0000${string}`;

const key = (a: string, b: string): Pair => `${a}\u0000${b}`;

export function trainBpe(corpus: string, numMerges: number): Array<[string, string]> {
  // Pre-split on whitespace; each word becomes a list of characters with a count.
  const words = new Map<string, number>();
  for (const w of corpus.split(/\s+/).filter(Boolean)) words.set(w, (words.get(w) ?? 0) + 1);
  let splits = [...words].map(([w, n]) => ({ symbols: [...w], count: n }));

  const merges: Array<[string, string]> = [];
  for (let m = 0; m < numMerges; m++) {
    const counts = new Map<Pair, number>();
    for (const { symbols, count } of splits)
      for (let i = 0; i < symbols.length - 1; i++) {
        const k = key(symbols[i], symbols[i + 1]);
        counts.set(k, (counts.get(k) ?? 0) + count);
      }
    if (counts.size === 0) break;
    const [best] = [...counts].sort((x, y) => y[1] - x[1])[0];
    const [a, b] = best.split("\u0000") as [string, string];
    merges.push([a, b]);
    splits = splits.map(({ symbols, count }) => ({ symbols: applyMerge(symbols, a, b), count }));
  }
  return merges;
}

function applyMerge(symbols: string[], a: string, b: string): string[] {
  const out: string[] = [];
  for (let i = 0; i < symbols.length; i++) {
    if (symbols[i] === a && symbols[i + 1] === b) {
      out.push(a + b);
      i++;
    } else out.push(symbols[i]);
  }
  return out;
}

export function encodeWord(word: string, merges: Array<[string, string]>): string[] {
  let symbols = [...word];
  for (const [a, b] of merges) symbols = applyMerge(symbols, a, b); // replay in learned order
  return symbols;
}

const merges = trainBpe("low low low lower lower lowest newest newest widest", 8);
console.log(merges.map(([a, b]) => `${a}+${b}`).join("  "));
console.log(encodeWord("lowest", merges)); // frequent pieces merge, e.g. ["low", "est"]
console.log(encodeWord("slower", merges)); // unseen word still encodes from smaller pieces

// Build and validate an SFT / DPO dataset as JSONL before spending GPU time on it.
import { createHash } from "node:crypto";
import { readFileSync, writeFileSync } from "node:fs";
import { z } from "zod";

const Sft = z.object({ prompt: z.string().min(1), response: z.string().min(1) });
const Pref = z.object({ prompt: z.string().min(1), chosen: z.string().min(1), rejected: z.string().min(1) });
type SftRow = z.infer<typeof Sft>;

const approxTokens = (s: string) => Math.ceil(s.length / 4); // estimate only; use the real tokenizer for limits
const hash = (s: string) => createHash("sha256").update(s.trim().toLowerCase()).digest("hex");

export function cleanSft(rows: unknown[], evalPrompts: Set<string>, maxTokens = 2048) {
  const seen = new Set<string>();
  const kept: SftRow[] = [];
  const dropped: Record<string, number> = { invalid: 0, duplicate: 0, tooLong: 0, leaksEval: 0 };

  for (const raw of rows) {
    const parsed = Sft.safeParse(raw);
    if (!parsed.success) { dropped.invalid++; continue; }
    const row = parsed.data;
    const h = hash(row.prompt);
    if (seen.has(h)) { dropped.duplicate++; continue; }
    if (evalPrompts.has(h)) { dropped.leaksEval++; continue; } // keep train and eval disjoint
    if (approxTokens(row.prompt + row.response) > maxTokens) { dropped.tooLong++; continue; }
    seen.add(h);
    kept.push(row);
  }
  return { kept, dropped };
}

export function splitTrainEval<T>(rows: T[], evalFraction = 0.1, seed = 42): { train: T[]; eval: T[] } {
  let s = seed;
  const rand = () => ((s = (s * 1664525 + 1013904223) % 2 ** 32) / 2 ** 32); // deterministic shuffle
  const shuffled = [...rows].sort(() => rand() - 0.5);
  const n = Math.max(1, Math.round(rows.length * evalFraction));
  return { eval: shuffled.slice(0, n), train: shuffled.slice(n) };
}

const toJsonl = (rows: unknown[]) => rows.map((r) => JSON.stringify(r)).join("\n") + "\n";

const raw = readFileSync("raw.jsonl", "utf8").trim().split("\n").map((l) => JSON.parse(l) as unknown);
const { train, eval: evalRows } = splitTrainEval(raw);
const evalHashes = new Set(evalRows.flatMap((r) => (Sft.safeParse(r).success ? [hash(Sft.parse(r).prompt)] : [])));
const { kept, dropped } = cleanSft(train, evalHashes);

writeFileSync("train.jsonl", toJsonl(kept));
writeFileSync("eval.jsonl", toJsonl(evalRows.filter((r) => Sft.safeParse(r).success)));
console.log({ train: kept.length, eval: evalRows.length, dropped });

// Preference pairs for DPO use the same checks plus: chosen !== rejected.
export const validPair = (r: unknown) => {
  const p = Pref.safeParse(r);
  return p.success && p.data.chosen.trim() !== p.data.rejected.trim();
};

// Measure TTFT and TPOT against any OpenAI-compatible endpoint (hosted API or a vLLM server).
import OpenAI from "openai";

const client = new OpenAI({
  baseURL: process.env.LLM_BASE_URL,   // e.g. http://localhost:8000/v1 for `vllm serve <model>`
  apiKey: process.env.LLM_API_KEY ?? "not-needed-for-local",
});
const MODEL = process.env.LLM_MODEL!;

type Sample = { ttftMs: number; tpotMs: number; outputChunks: number; totalMs: number };

async function measure(prompt: string): Promise<Sample> {
  const start = performance.now();
  let first = 0;
  let last = 0;
  let chunks = 0;

  const stream = await client.chat.completions.create({
    model: MODEL,
    messages: [{ role: "user", content: prompt }],
    max_tokens: 256,
    stream: true,
  });
  for await (const chunk of stream) {
    if (!chunk.choices[0]?.delta?.content) continue;
    const now = performance.now();
    if (chunks === 0) first = now;
    last = now;
    chunks++;
  }
  // Chunks approximate tokens; servers may group several tokens per chunk.
  const ttftMs = first - start;
  const tpotMs = chunks > 1 ? (last - first) / (chunks - 1) : 0;
  return { ttftMs, tpotMs, outputChunks: chunks, totalMs: last - start };
}

const pct = (xs: number[], p: number) => {
  const s = [...xs].sort((a, b) => a - b);
  return s[Math.min(s.length - 1, Math.floor((p / 100) * s.length))];
};

async function main() {
  const prompts = Array.from({ length: 20 }, (_, i) => `Explain topic #${i} of distributed systems in 5 sentences.`);
  const results: Sample[] = [];
  const concurrency = 5;
  for (let i = 0; i < prompts.length; i += concurrency) {
    results.push(...(await Promise.all(prompts.slice(i, i + concurrency).map(measure))));
  }
  const ttft = results.map((r) => r.ttftMs);
  const tpot = results.map((r) => r.tpotMs);
  console.table({
    ttft: { p50: pct(ttft, 50), p95: pct(ttft, 95) },
    tpot: { p50: pct(tpot, 50), p95: pct(tpot, 95) },
  });
}

main().catch((e) => {
  console.error(e);
  process.exit(1);
});
